<script lang="ts">
  import { onMount } from 'svelte';
  import { taskStatuses, parseWorkspaceData, workspaceKey, type LocalTask, type TaskStatus } from '$lib/pi/tasks';
  import type { PiSessionSummary, GitStatus } from '$lib/pi/api';
  let { view, sessions, cwd, sessionId, sessionPath, sessionName, stateLabel, connected, locked, repo, tools, logs, onview, onopen, onnew, onprepare } : {
    view:string; sessions:PiSessionSummary[]; cwd:string; sessionId:string; sessionPath:string; sessionName:string; stateLabel:string; connected:boolean; locked:boolean; repo:GitStatus|null;
    tools:Array<{id:string;name:string;status:string;detail:string}>;logs:string[];
    onview:(view:string)=>void;onopen:(path:string)=>void;onnew:(cwd:string)=>void;onprepare:(cwd:string,title:string)=>Promise<string>;
  } = $props();
  let tasks = $state<LocalTask[]>([]), savedWorkspaces = $state<string[]>([]), ready = $state(false), error = $state('');
  let search = $state(''), filter = $state(''), statusFilter = $state(''), title = $state(''), workspace = $state(''), newPath = $state(''), saving = $state(false);
  const workspaces = $derived([...new Set([...savedWorkspaces,cwd,...sessions.map(s=>s.cwd)].filter(Boolean))]);
  const visibleTasks = $derived(tasks.filter(t=>(!filter||t.workspace===filter)&&(!statusFilter||t.status===statusFilter)&&`${t.title} ${t.workspace}`.toLowerCase().includes(search.toLowerCase())));
  const recent = $derived([...sessions].sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt)));
  function persist() { try { localStorage.setItem(workspaceKey,JSON.stringify({workspaces:savedWorkspaces,tasks}));error=''; } catch { error='Changes are only in memory: browser storage is unavailable. Export tasks before leaving this page.'; } }
  function addTask(event:SubmitEvent) {event.preventDefault(); if(!ready||!title.trim())return;tasks=[{id:crypto.randomUUID(),title:title.trim(),workspace:workspace.trim(),status:'Planned',updatedAt:new Date().toISOString()},...tasks];title='';persist();}
  function update(id:string,status:TaskStatus) {tasks=tasks.map(t=>t.id===id?{...t,status,updatedAt:new Date().toISOString()}:t);persist();}
  async function prepare(t:LocalTask) {saving=true;error='';try{const path=await onprepare(t.workspace,t.title);tasks=tasks.map(x=>x.id===t.id?{...x,sessionPath:path,updatedAt:new Date().toISOString()}:x);persist();}catch(e){error=String(e);}finally{saving=false;}}
  function exportTasks(){const url=URL.createObjectURL(new Blob([JSON.stringify({workspaces:savedWorkspaces,tasks},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='pi-console-tasks.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  onMount(()=>{try{const data=parseWorkspaceData(localStorage.getItem(workspaceKey));tasks=data.tasks;savedWorkspaces=data.workspaces;ready=true;}catch(e){error=String(e);}workspace=cwd;});
</script>
<div class="workspace-page">
  <header><div><h1>{view==='overview'?'Your workspace, at a glance':view==='tasks'?'Tasks and activity':view==='activity'?'Session activity':'Workspaces'}</h1><p>{view==='overview'?'A clear view of your local coding work.':view==='tasks'?'Plan and track work across your repositories. Task statuses are set by you.':view==='activity'?'Actual tool calls and protocol events from the connected session.':'Your repositories and their saved conversations.'}</p></div><span class="state">{stateLabel}</span></header>
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if view==='overview'}
    <h2>Active session</h2>
    <section class="active-session"><div class="active-heading"><span class="repo-icon">〈〉</span><div><h3>{sessionName || cwd.split('/').pop() || 'No workspace connected'}</h3><p>{cwd || 'Open the desktop app to connect your Pi harness.'}</p></div></div>
      <dl><div><dt>Branch</dt><dd>{repo?.branch || 'Unavailable'}</dd></div><div><dt>Session</dt><dd title={sessionId}>{sessionId ? sessionId.slice(0,12) : 'Not connected'}</dd></div><div><dt>Agent status</dt><dd>{stateLabel}</dd></div></dl>
      <div class="active-body"><div><h4>Continue the conversation</h4><p>{sessionName || 'Review messages, inspect changes, or describe the next task.'}</p><button class="primary" onclick={()=>onview('sessions')}>{connected?'Open session':'Open console'} →</button></div><div><h4>Live activity</h4>{#each tools.slice(-4).reverse() as tool}<div class="activity-row"><span class:failed={tool.status==='Error'}>{tool.status}</span><strong>{tool.name}</strong></div>{:else}<p>No tool activity recorded. Nothing is running in browser preview.</p>{/each}<button class="link" onclick={()=>onview('activity')}>View full activity ↗</button></div></div>
    </section>
    <div class="overview-grid"><div><h2>Workspaces <button class="link" onclick={()=>onview('workspaces')}>View all</button></h2><section>{#each workspaces.slice(0,5) as path}<button class="workspace-row" disabled={locked} onclick={()=>onnew(path)}><span class="repo-icon small">〈〉</span><span><strong>{path.split('/').pop()}</strong><small>{path}</small></span><span>→</span></button>{:else}<p>No saved workspaces. Add a repository to get started.</p>{/each}<button class="link" onclick={()=>onview('workspaces')}>＋ Add workspace</button></section></div>
    <div><h2>Recent sessions <button class="link" onclick={()=>onview('sessions')}>View all</button></h2><section>{#each recent.slice(0,5) as s}<button class="workspace-row" disabled={locked} onclick={()=>onopen(s.path)}><span><strong>{s.title || 'Untitled'}</strong><small>{s.cwd.split('/').pop()}</small></span><time>{new Date(s.updatedAt).toLocaleDateString()}</time></button>{:else}<p>Connected session history will appear here.</p>{/each}</section></div></div>
  {:else if view==='workspaces'}
    <form class="add-row" onsubmit={(e)=>{e.preventDefault();if(ready&&newPath.trim()){savedWorkspaces=[...new Set([...savedWorkspaces,newPath.trim()])];newPath='';persist();}}}><label>Repository directory<input bind:value={newPath} placeholder="/absolute/path/to/repository" required pattern="/.*" /></label><button class="primary" disabled={!ready}>Add workspace</button></form>
    <p>Saved locally. Opening validates the directory and starts a new Pi session there; no prompt is sent.</p><div class="workspace-grid">{#each workspaces as path}<section><span class="repo-icon">〈〉</span><h3>{path.split('/').pop()}</h3><p class="path">{path}</p><p>{sessions.filter(s=>s.cwd===path).length} saved sessions</p><button class="primary" disabled={locked} onclick={()=>onnew(path)}>Open workspace →</button>{#if savedWorkspaces.includes(path)}<button class="link" onclick={()=>{savedWorkspaces=savedWorkspaces.filter(p=>p!==path);persist();}}>Unpin</button>{/if}</section>{:else}<section><h3>Make room for your next idea</h3><p>Add a repository above. Existing session workspaces are discovered when connected.</p></section>{/each}</div>
  {:else if view==='tasks'}
    <div class="filters"><input aria-label="Search tasks" placeholder="Search tasks or repositories…" bind:value={search}/><select aria-label="Filter task workspace" bind:value={filter}><option value="">All workspaces</option>{#each workspaces as path}<option value={path}>{path.split('/').pop()}</option>{/each}</select><select aria-label="Filter task status" bind:value={statusFilter}><option value="">All statuses</option>{#each taskStatuses as status}<option>{status}</option>{/each}</select><button onclick={exportTasks}>Export</button></div>
    <form class="add-row" onsubmit={addTask}><label>Task title<input aria-label="Task title" bind:value={title} required maxlength="1000" placeholder="Describe the work to track"/></label><label>Workspace<input aria-label="Task workspace" list="task-workspaces" bind:value={workspace} placeholder="/path/to/repository"/></label><datalist id="task-workspaces">{#each workspaces as path}<option value={path}></option>{/each}</datalist><button class="primary" disabled={!ready || !title.trim()}>Add task</button></form>
    <p>Local task board · statuses are your labels, not claims that Pi ran tests or merged code. Preparing a session only fills a draft; you choose when to send.</p>
    {#each taskStatuses as status}{@const group=visibleTasks.filter(t=>t.status===status)}{#if group.length}<h2>{status} <span>({group.length})</span></h2><section class="task-group">{#each group as t}<article class="task-row"><div class="task-repo"><span class="repo-icon small">〈〉</span><span>{t.workspace.split('/').pop() || 'No workspace'}<small title={t.workspace}>{t.workspace}</small></span></div><strong>{t.title}</strong><select aria-label={`Status for ${t.title}`} value={t.status} onchange={(e)=>update(t.id,e.currentTarget.value as TaskStatus)}>{#each taskStatuses as option}<option>{option}</option>{/each}</select><time>{new Date(t.updatedAt).toLocaleDateString()}</time><div class="task-actions">{#if t.sessionPath}<button disabled={locked} onclick={()=>onopen(t.sessionPath!)}>Open session ↗</button>{:else}<button disabled={locked || saving || !t.workspace} onclick={()=>prepare(t)}>Prepare session</button>{/if}<button aria-label={`Delete ${t.title}`} onclick={()=>{if(confirm(`Delete local task "${t.title}"? Session history is kept.`)){tasks=tasks.filter(x=>x.id!==t.id);persist();}}}>×</button></div></article>{/each}</section>{/if}{/each}
    {#if !visibleTasks.length}<section><h3>{tasks.length?'No matching tasks':'What would you like to work on?'}</h3><p>Add a local task above. Your board is separate from Pi session history.</p></section>{/if}
  {:else}
    <div class="filters"><input aria-label="Search activity" bind:value={search} placeholder="Search tool names or output…"/><span>{tools.length} recorded tools</span></div>
    {#each tools.filter(t=>`${t.name} ${t.detail}`.toLowerCase().includes(search.toLowerCase())).slice().reverse() as tool}<details class="activity"><summary><span class:failed={tool.status==='Error'}>{tool.status}</span><strong>{tool.name}</strong><code>{tool.id}</code></summary><pre>{tool.detail.slice(0,20000)}{tool.detail.length>20000?'\n… Output preview limited to 20,000 characters.':''}</pre></details>{:else}<section><h3>No recorded activity</h3><p>Tool executions from the connected session appear here. Open a saved session to inspect its history.</p></section>{/each}
    <details class="activity"><summary>Protocol log · {logs.length} recent events</summary>{#each logs as log}<pre>{log.slice(0,20000)}</pre>{/each}</details>
  {/if}
</div>
<style>
  .workspace-page{flex:1;overflow:auto;min-height:0;padding:35px 40px 50px}header{display:flex;align-items:start;justify-content:space-between;gap:20px;margin-bottom:32px}h1{font-size:29px;line-height:1.3;letter-spacing:-.7px;font-weight:550;margin:0}p{color:var(--muted);font-size:12px;line-height:1.7}header p{font-size:14px}h2{display:flex;align-items:center;gap:10px;color:var(--accent);font-size:15px;font-weight:550;margin:24px 0 12px}h2 button{margin-left:auto}h3{font-size:19px;font-weight:550;margin:10px 0 0}h4{font-size:14px;margin:0 0 10px;font-weight:500}.state{font-size:12px;color:var(--muted);white-space:nowrap}section{background:var(--glass);border:1px solid var(--border-soft);border-radius:7px;padding:20px;min-width:0}.active-session{padding:0}.active-heading{display:flex;gap:20px;align-items:center;padding:25px}.active-heading h3{font-size:23px;margin:0}.active-heading p{margin:4px 0}.repo-icon{display:inline-grid;place-items:center;width:54px;height:54px;border:1px solid var(--border);border-radius:6px;font-size:24px;flex-shrink:0}.repo-icon.small{width:31px;height:31px;font-size:14px}dl{display:grid;grid-template-columns:repeat(3,1fr);padding:0 25px 24px;margin:0;gap:20px}dl div+div{border-left:1px solid var(--border);padding-left:24px}dt{color:var(--muted);font-size:12px}dd{margin:5px 0;color:var(--accent);font-size:14px}.active-body{display:grid;grid-template-columns:1fr 1.3fr;border-top:1px solid var(--border-soft)}.active-body>div{padding:24px}.active-body>div+div{border-left:1px solid var(--border-soft)}.active-body .primary{margin-top:25px}.activity-row{display:flex;gap:15px;border-bottom:1px solid var(--border-soft);padding:10px 0;font-size:12px}.activity-row span{color:var(--muted)}.overview-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.workspace-row{display:flex;text-align:left;align-items:center;gap:15px;width:100%;border:0;border-bottom:1px solid var(--border-soft);border-radius:0;background:transparent;padding:15px 0}.workspace-row>span:nth-last-child(2){flex:1;min-width:0}.workspace-row strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;font-weight:500}small{display:block;color:var(--muted);font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:260px}time{color:var(--muted);font-size:11px;white-space:nowrap}.link{border:0;color:var(--accent);background:transparent;padding:7px 0;font-size:12px}.workspace-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}.path{overflow-wrap:anywhere}.add-row,.filters{display:flex;align-items:end;gap:12px;margin-bottom:18px}.filters{align-items:center}.add-row label{display:grid;gap:7px;flex:1;font-size:12px;color:var(--muted);min-width:0}.filters>input{flex:1;min-width:150px}.task-group{padding:0}.task-row{display:grid;grid-template-columns:minmax(140px,1fr) minmax(160px,1.5fr) 135px 90px auto;align-items:center;gap:15px;padding:18px;border-bottom:1px solid var(--border-soft)}.task-row:last-child{border-bottom:0}.task-row strong{font-size:13px;font-weight:500;overflow-wrap:anywhere}.task-repo{display:flex;align-items:center;gap:10px;min-width:0;font-size:12px}.task-repo small{max-width:160px}.task-actions{display:flex;gap:6px}.task-actions button{font-size:11px}.activity{border:1px solid var(--border-soft);border-radius:5px;margin:12px 0;background:var(--glass)}summary{padding:16px;display:flex;gap:20px;align-items:center;cursor:pointer;font-size:12px}summary code{margin-left:auto;color:var(--muted)}pre{overflow:auto;max-height:400px;white-space:pre-wrap;overflow-wrap:anywhere;padding:18px}.failed,.error{color:var(--bad)}@media(max-width:1150px){.workspace-page{padding:25px}.task-row{grid-template-columns:1fr 1.3fr 135px}.task-actions{grid-column:2/-1}time{display:none}}@media(max-width:760px){header{display:block}h1{font-size:24px}.workspace-page{padding:20px 15px}.overview-grid,.active-body{grid-template-columns:1fr}.active-body>div+div{border-left:0;border-top:1px solid var(--border-soft)}.filters,.add-row{flex-wrap:wrap}.add-row label{flex-basis:100%}.task-row{grid-template-columns:1fr}.task-actions{grid-column:auto}dl{gap:10px;padding:0 16px 18px}dl div+div{padding-left:10px}dd{font-size:12px}.active-heading{padding:18px}}
</style>
